def solve():
    x, y, z, k = map(int, input().split())
    a = sorted(map(int, input().split()), reverse=True)
    b = sorted(map(int, input().split()), reverse=True)
    c = sorted(map(int, input().split()), reverse=True)

    sums = []
    for ai in a:
        for bj in b:
            for ck in c:
                heapq.heappush(sums, -(ai + bj + ck))
                if len(sums) > k:
                    heapq.heappop(sums)

    top_k_sums = sorted([-s for s in sums], reverse=True)
    for s in top_k_sums:
