from typing import List

def count_integer_distances(n: int, d: int, x: List[List[int]]) -> int:
    cnt = 0
    for i in range(n):
        for j in range(i+1, n):
            dist = sum((x[i][k] - x[j][k]) ** 2 for k in range(d))
            if dist == int(sqrt(dist)) ** 2:
                cnt += 1
    return cnt

def main():
    n, d = map(int, input().split())
    x = [list(map(int, input().split())) for i in range(n)]
    print(count_integer_distances(n, d, x))

